from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(grid[r][0] for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]))
    hseps = [r for r, row in enumerate(grid) if all(v == divider for v in row)]
    wseps = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]
    row_ranges = []
    start = 0
    for sep in hseps:
        if sep > start:
            row_ranges.append((start, sep))
        start = sep + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for sep in wseps:
        if sep > start:
            col_ranges.append((start, sep))
        start = sep + 1
    if start < w:
        col_ranges.append((start, w))

    # The pattern is the non-divider object outside the first column of tiles.
    pattern_color = next(
        grid[r][c]
        for ti, (r0, r1) in enumerate(row_ranges)
        for tj, (c0, c1) in enumerate(col_ranges)
        if tj > 0
        for r in range(r0, r1) for c in range(c0, c1)
        if grid[r][c] not in (0, divider)
    )
    template = next(
        (r0, r1, c0, c1)
        for r0, r1 in row_ranges
        for c0, c1 in col_ranges[1:]
        if any(grid[r][c] == pattern_color for r in range(r0, r1) for c in range(c0, c1))
    )
    tr0, tr1, tc0, tc1 = template
    pattern = [(r - tr0, c - tc0) for r in range(tr0, tr1) for c in range(tc0, tc1) if grid[r][c] == pattern_color]

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(row_ranges):
        counts = Counter(v for r in range(r0, r1) for c in range(col_ranges[0][0], col_ranges[0][1]) if (v := grid[r][c]) not in (0, divider))
        seed_color = counts.most_common(1)[0][0]
